import { dispatchPluginReply } from '../../../server/rpc/handlers/plugin-dispatch.js';
import { startFinetune } from '../../../server/bare/plugins/llamacpp-completion/ops/finetune.js';
export async function handleFinetune(request, progressCallback) {
    if (progressCallback &&
        (request.operation === 'start' ||
            request.operation === 'resume' ||
            request.operation === undefined)) {
        return startFinetune(request, (progress) => {
            const update = {
                type: 'finetune:progress',
                modelId: request.modelId,
                ...progress
            };
            progressCallback(update);
        });
    }
    return dispatchPluginReply(request.modelId, 'finetune', request);
}
